def transform(grid):
    """Complete the bounding rectangle around the sparse marker pattern, including evidenced inner rails."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != background), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    out = [row[:] for row in grid]
    if not points:
        return out

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    def fill(r, c):
        if grid[r][c] == background:
            out[r][c] = 2

    # Draw the outside frame through the extreme marker rows and columns.
    for c in range(c0, c1 + 1):
        fill(r0, c)
        fill(r1, c)
    for r in range(r0, r1 + 1):
        fill(r, c0)
        fill(r, c1)

    # Extend any internal line that reaches both opposite frame edges and
    # already has marker evidence between them.
    for c in range(c0 + 1, c1):
        if grid[r0][c] == marker and grid[r1][c] == marker:
            if any(grid[r][c] == marker for r in range(r0 + 1, r1)):
                for r in range(r0 + 1, r1):
                    fill(r, c)
    for r in range(r0 + 1, r1):
        if grid[r][c0] == marker and grid[r][c1] == marker:
            if any(grid[r][c] == marker for c in range(c0 + 1, c1)):
                for c in range(c0 + 1, c1):
                    fill(r, c)
    return out

